import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        arr = []
        for _ in range(n):
            arr.append(next(iterator))
    except StopIteration:
        return

    if n == 0:
        print(0)
        return

    # Count in-degrees and out-degrees for each character
    # We treat each string as a directed edge from first char to last char
    # For a valid Eulerian circuit (circle), in-degree must equal out-degree for all nodes
    # And the graph must be connected (considering only nodes with edges)

    in_degree = {}
    out_degree = {}

    for s in arr:
        start_char = s[0]
        end_char = s[-1]

        out_degree[start_char] = out_degree.get(start_char, 0) + 1
        in_degree[end_char] = in_degree.get(end_char, 0) + 1

        # Ensure all characters are present in both dicts
        if start_char not in in_degree:
            in_degree[start_char] = 0
        if end_char not in out_degree:
            out_degree[end_char] = 0

    # Check condition 1: in-degree == out-degree for all characters
    all_chars = set(in_degree.keys()) | set(out_degree.keys())
    for char in all_chars:
        if in_degree.get(char, 0) != out_degree.get(char, 0):
            print(0)
            return

    # Check condition 2: The graph must be connected
    # We use Union-Find to check connectivity of nodes involved in edges
    parent = {}

    def find(x):
        if x not in parent:
            parent[x] = x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    # Union the start and end characters for each string
    for s in arr:
        u = s[0]
        v = s[-1]
        union(u, v)

    # Find the number of connected components among the active nodes
    roots = set()
    for char in all_chars:
        roots.add(find(char))

    if len(roots) > 1:
        print(0)
    else:
        print(1)

if __name__ == "__main__":
    solve()
